// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/healthz", wrapper.GetCoreHealth)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/me", wrapper.GetMe)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/target-profile", wrapper.GetTargetProfile)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/v1/target-profile", wrapper.PutTargetProfile)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/daily-plan", wrapper.GetDailyPlan)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/practice-modes", wrapper.ListPracticeModes)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/practice-activities", wrapper.CreatePracticeActivity)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/practice-activities/{practice_activity_id}", wrapper.GetPracticeActivity)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/practice-activities/{practice_activity_id}/media/{media_reference}", wrapper.GetPracticeActivityMedia)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/attempts", wrapper.CreateAttempt)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/attempts/{attempt_id}", wrapper.GetAttempt)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/v1/attempts/{attempt_id}", wrapper.PatchAttempt)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/attempts/{attempt_id}/submissions", wrapper.SubmitAttempt)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/evaluations/{evaluation_id}", wrapper.GetEvaluation)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/progress", wrapper.GetProgress)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/gaps", wrapper.ListGaps)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/review-queue", wrapper.GetReviewQueue)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/event-stream", wrapper.StreamResourceEvents)
	})

	return r
}

